import sys

def main():
    # Read all input from standard input
    # sys.stdin.read().split() reads the entire input and splits by whitespace,
    # handling newlines and spaces automatically.
    input_data = sys.stdin.read().split()

    if not input_data:
        return

    iterator = iter(input_data)

    # Read N (number of ARCs) and R (initial rating)
    try:
        N = int(next(iterator))
        R = int(next(iterator))
    except StopIteration:
        return

    # Process each of the N contests
    for _ in range(N):
        try:
            D = int(next(iterator))
            A = int(next(iterator))
        except StopIteration:
            break

        # Determine if rating update applies
        # In ARC Div. 1 (D=1), rating update applies if the current rating R is between 1600 and 2799 inclusive.
        # In ARC Div. 2 (D=2), rating update applies if the current rating R is between 1200 and 2399 inclusive.
        # If an update applies, the rating increases by A.
        # The updated rating becomes the starting rating for the next contest.

        if D == 1:
            if 1600 <= R <= 2799:
                R += A
        elif D == 2:
            if 1200 <= R <= 2399:
                R += A

    # Print the final rating after all N contests
    print(R)

if __name__ == '__main__':
    main()

class Solution:
    def minBitwiseArray(self, nums: List[int]) -> List[int]:
        ans = []
        for n in nums:
            if n == 2:
                ans.append(-1)
            else:
                # Count trailing ones in n
                # Since n is a prime > 2, n is odd.
                # We can count how many consecutive 1s are at the end of n's binary representation.
                cnt = 0
                temp = n
                while (temp & 1):
                    cnt += 1
                    temp >>= 1

                # The formula derived is x = n - 2^(cnt-1)
                # This x is the smallest non-negative integer satisfying x | (x+1) = n
                ans.append(n - (1 << (cnt - 1)))
        return ans

from typing import List

class Solution:
    def buttonWithLongestTime(self, events: List[List[int]]) -> int:
        max_duration = 0
        best_index = -1

        # Iterate through each event in the sorted list
        for i in range(len(events)):
            idx, time = events[i]

            # Determine the duration of the current button press
            # For the first event, the duration is simply the time it was pressed.
            # For subsequent events, the duration is the difference between the current time 
            # and the time of the previous event.
            if i == 0:
                duration = time
            else:
                duration = time - events[i-1][1]

            # Check if the current duration is greater than the maximum found so far
            if duration > max_duration:
                max_duration = duration
                best_index = idx
            # If the duration is equal to the maximum, update the best_index if the current button index is smaller
            elif duration == max_duration:
                if idx < best_index:
                    best_index = idx

        return best_index
